dashboard.definition:
{
  "title": "ABAP Operations",
  "description": "Operational health of SAP ABAP application layer — work processes, dispatcher, enqueue, and instance activity",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_total": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_total"
      },
      "title": "Total Events",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_sids": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_sids"
      },
      "title": "Active SIDs",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_wp_errors": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_wp_errors"
      },
      "title": "Dispatcher Errors",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_volume_by_type": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_volume_by_type"
      },
      "title": "Event Volume by Sourcetype",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_uptime": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_uptime"
      },
      "title": "System Uptime (Latest)",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_dispatcher_severity": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_dispatcher_severity"
      },
      "title": "Dispatcher Severity Over Time",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_wp_categories": {
      "type": "splunk.pie",
      "dataSources": {
        "primary": "ds_wp_categories"
      },
      "title": "Work Process Categories",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "showDonutHole": true,
        "backgroundColor": "transparent",
        "legendDisplay": "bottom",
        "legendTruncation": "ellipsisMiddle"
      }
    },
    "viz_wp_functions": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_wp_functions"
      },
      "title": "Top Work Process Functions",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_enqueue_timeline": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_enqueue_timeline"
      },
      "title": "Enqueue Lock Activity",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_sid_instance": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_sid_instance"
      },
      "title": "Activity by SID / Instance / Type",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_rect_row1_left": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_row1_right": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_row2_left": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_row2_mid": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_row2_right": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_row3_left": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_row3_right": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_rect_1": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_2": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_3": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/applications/#abap-operations",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_total": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:abap:dispatcher\", \"sap:abap:enqueueserver\", \"sap:abap:event\", \"sap:abap:messageserver\", \"sap:abap:sapstartsrv\", \"sap:abap:workprocess\") | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_sids": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:abap:dispatcher\", \"sap:abap:enqueueserver\", \"sap:abap:event\", \"sap:abap:messageserver\", \"sap:abap:sapstartsrv\", \"sap:abap:workprocess\") | eventstats dc(sap_sid) as window_dc | timechart span=1d dc(sap_sid) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]"
      }
    },
    "ds_kpi_wp_errors": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:dispatcher\" (dp_severity=\"ERROR\" OR dp_severity=\"FATAL\") | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_volume_by_type": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:abap:dispatcher\", \"sap:abap:enqueueserver\", \"sap:abap:event\", \"sap:abap:messageserver\", \"sap:abap:sapstartsrv\", \"sap:abap:workprocess\") | timechart span=1d count by sourcetype"
      }
    },
    "ds_uptime": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:event\" uptime_days=* | stats latest(uptime_days) as \"Uptime (Days)\" latest(uptime_hours) as \"Uptime (Hours)\" by sap_sid sap_instance | sort sap_sid sap_instance | rename sap_sid as SID sap_instance as Instance"
      }
    },
    "ds_dispatcher_severity": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:dispatcher\" dp_severity=* | timechart span=1d count by dp_severity"
      }
    },
    "ds_wp_categories": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" wp_category_name=* | stats count by wp_category_name | sort -count"
      }
    },
    "ds_wp_functions": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" wp_function=* | stats count as Events by wp_function wp_sub_function | sort -Events | head 20 | rename wp_function as \"Function\" wp_sub_function as \"Sub-Function\""
      }
    },
    "ds_enqueue_timeline": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:enqueueserver\" | timechart span=1d count as \"Lock Operations\""
      }
    },
    "ds_sid_instance": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:abap:dispatcher\", \"sap:abap:enqueueserver\", \"sap:abap:event\", \"sap:abap:messageserver\", \"sap:abap:sapstartsrv\", \"sap:abap:workprocess\") | stats count by sap_sid sourcetype | sort -count | head 30"
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "options": {
          "display": "fit-to-width",
          "height": 1371,
          "width": 1920,
          "backgroundColor": "#0d1117"
        },
        "structure": [
          {
            "item": "viz_nav_go",
            "type": "block",
            "position": {
              "x": 10,
              "y": 10,
              "w": 120,
